const statusMeta: Record<Status,{label:string; className:string}> = {
  new:{label:"جديد",className:"status-new"}, confirmed:{label:"مؤكد",className:"status-confirmed"}, arrived:{label:"حضر",className:"status-arrived"}, completed:{label:"مكتمل",className:"status-completed"}, cancelled:{label:"ملغي",className:"status-cancelled"}, no_show:{label:"لم يحضر",className:"status-no-show"},
};
const pad = (n:number) => String(n).padStart(2,"0");
const timeLabel = (minutes:number) => `${pad(Math.floor(minutes / 60))}:${pad(minutes % 60)}`;
const isoDate = (date:Date, timeZone?:string) => {
  if (!timeZone) return date.toISOString().slice(0,10);
  const parts = new Intl.DateTimeFormat("en-CA",{timeZone,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(date);
  const values = Object.fromEntries(parts.map(part => [part.type,part.value]));
  return `${values.year}-${values.month}-${values.day}`;
};
const bookingFromDatabase = (row:{id:number;date:string;clientName:string;clientPhone:string;serviceName:string;staffId:number;startMinutes:number;durationMinutes:number;price:number;status:Status;paid:number;note:string|null}):Booking => ({id:row.id,date:row.date,client:row.clientName,phone:row.clientPhone,service:row.serviceName,staff:row.staffId,start:row.startMinutes,duration:row.durationMinutes,price:row.price,status:row.status,paid:Boolean(row.paid),note:row.note ?? ""});
const notificationText = (action:string) => action === "booking.created" ? "وصل حجز أونلاين جديد" : action === "booking.cancelled" ? "تم إلغاء حجز" : action === "booking.paid" ? "تم تسجيل دفعة حجز" : "تم تحديث حجز";

export default function Home() {
  const [active, setActive] = useState("dashboard");
  const [navItems, setNavItems] = useState(navDefaults);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [services, setServices] = useState<Service[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [selectedId, setSelectedId] = useState(1);
  const [dateOffset, setDateOffset] = useState(0);
  const [view, setView] = useState<"day"|"week">("day");
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<Status | "all">("all");
  const [modal, setModal] = useState<"new"|"customize"|"company"|null>(null);
  const [editEntity, setEditEntity] = useState<{kind:"staff"|"service"; id:number} | null>(null);
  const [scheduleStaffId, setScheduleStaffId] = useState<number | null>(null);
  const [newServiceOpen, setNewServiceOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [accent, setAccent] = useState("#0d8f83");
  const [compact, setCompact] = useState(false);
  const [dragging, setDragging] = useState<number | null>(null);
  const [toast, setToast] = useState("");
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [ownerMenuOpen, setOwnerMenuOpen] = useState(false);
  const [currentTime, setCurrentTime] = useState(() => new Date());
  const {language,setLanguage,t} = useLanguage();
  const [country,setCountry] = useState(() => (typeof window !== "undefined" && localStorage.getItem("clientora-country")) || "OM");
  const today = useMemo(() => new Date(), []);
  const displayDate = useMemo(() => { const date = new Date(today); date.setDate(date.getDate() + dateOffset); return date; }, [today,dateOffset]);
  const workspaceQuery = trpc.workspace.current.useQuery();
  const accessContextQuery = trpc.workspace.accessContext.useQuery();
  const isStaffAccount = accessContextQuery.data?.role === "staff";
  const tenantId = workspaceQuery.data?.id;
  const selectedIsoDate = isoDate(displayDate,workspaceQuery.data?.timezone ?? "Asia/Muscat");
  const weekEndDate = (() => { const date = new Date(selectedIsoDate+"T12:00:00Z"); date.setUTCDate(date.getUTCDate()+6); return date.toISOString().slice(0,10); })();
  const bookingsQuery = trpc.workspace.bookings.useQuery({tenantId:tenantId ?? 0,date:selectedIsoDate,...(view === "week" ? {endDate:weekEndDate} : {})},{enabled:Boolean(tenantId)&&accessContextQuery.isSuccess&&accessContextQuery.data?.role!=="staff"});
  const staffQuery = trpc.workspace.staff.useQuery({tenantId:tenantId ?? 0},{enabled:Boolean(tenantId)&&accessContextQuery.isSuccess&&accessContextQuery.data?.role!=="staff"});
  const servicesQuery = trpc.workspace.services.useQuery({tenantId:tenantId ?? 0},{enabled:Boolean(tenantId)&&accessContextQuery.isSuccess&&accessContextQuery.data?.role!=="staff"});
  const createServiceMutation = trpc.workspace.createService.useMutation({onSuccess:()=>{servicesQuery.refetch();setNewServiceOpen(false);notify("تمت إضافة الخدمة وحفظها");},onError:error=>notify(error.message)});
  const updateServiceMutation = trpc.workspace.updateService.useMutation({onSuccess:()=>{servicesQuery.refetch();setEditEntity(null);notify("تم حفظ تعديلات الخدمة");},onError:error=>notify(error.message)});
  const addStaffMutation = trpc.workspace.addStaff.useMutation({onSuccess:()=>{staffQuery.refetch();setEditEntity(null);notify("تمت إضافة الموظف");},onError:error=>notify(error.message)});
  const updateStaffMutation = trpc.workspace.updateStaff.useMutation({onSuccess:()=>{staffQuery.refetch();setEditEntity(null);notify("تم حفظ بيانات الموظف");},onError:error=>notify(error.message)});
  const createInviteMutation = trpc.workspace.createInvite.useMutation({onSuccess:invite=>{if(navigator.clipboard?.writeText){navigator.clipboard.writeText(invite.code).then(()=>notify("تم إنشاء كود الدعوة ونسخه؛ أرسله للموظف")).catch(()=>notify("كود دعوة الموظف: "+invite.code));}else notify("كود دعوة الموظف: "+invite.code);},onError:error=>notify(error.message)});
  const notificationsQuery = trpc.workspace.notifications.useQuery({tenantId:tenantId ?? 0},{enabled:Boolean(tenantId)&&accessContextQuery.isSuccess&&accessContextQuery.data?.role!=="staff",refetchInterval:30000});
  const updateSettings = trpc.workspace.updateSettings.useMutation({onSuccess:()=>notify("تم حفظ البلد والعملة")});
  const createBookingMutation = trpc.workspace.createBooking.useMutation({onSuccess:()=>{bookingsQuery.refetch();notificationsQuery.refetch();setModal(null);notify("تم إنشاء الحجز وحفظه في قاعدة البيانات");},onError:error=>notify(error.message)});
  const notify = (message:string) => { setToast(message); window.setTimeout(() => setToast(""), 2400); };

  useEffect(() => { const timer = window.setInterval(() => setCurrentTime(new Date()), 30000); return () => window.clearInterval(timer); }, []);
  const bookingUpdate = trpc.workspace.updateBooking.useMutation({onSuccess:()=>{bookingsQuery.refetch();notificationsQuery.refetch();notify("تم حفظ تحديث الحجز");},onError:error=>notify(error.message)});
  const logoutMutation = trpc.auth.logout.useMutation({onSuccess:()=>window.location.assign("/login"),onError:error=>notify(error.message)});
  const selected = bookings.find(b => b.id === selectedId) ?? null;
  const locale = language === "en" ? "en-GB" : language === "ru" ? "ru-RU" : "ar-OM";
  const weekLocale = locale;
  const businessTimeZone = workspaceQuery.data?.timezone ?? "Asia/Muscat";
  const dayText = displayDate.toLocaleDateString(locale,{weekday:"long",day:"numeric",month:"long",year:"numeric",timeZone:businessTimeZone});
  const currentDateInBusinessZone = isoDate(currentTime,businessTimeZone);
  const currentTimeParts = new Intl.DateTimeFormat("en-GB",{timeZone:businessTimeZone,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).format(currentTime).split(":").map(Number);
  const currentMinutes = currentTimeParts[0]*60+currentTimeParts[1];
  const showCurrentTimeLine = active === "schedule" && view === "day" && selectedIsoDate === currentDateInBusinessZone && currentMinutes >= 540 && currentMinutes <= 1080;
  const filtered = useMemo(() => bookings.filter(b => (!query || `${b.client} ${b.phone} ${b.service}`.includes(query)) && (filter === "all" || b.status === filter)), [bookings, query, filter]);
  useEffect(() => { if (bookingsQuery.data) { setBookings(bookingsQuery.data.map(bookingFromDatabase)); setSelectedId(current => bookingsQuery.data.some(item => item.id === current) ? current : (bookingsQuery.data[0]?.id ?? 0)); } }, [bookingsQuery.data]);
  useEffect(() => { if (staffQuery.data) setStaff(staffQuery.data.map(item => ({id:item.id,name:item.name,role:item.role,color:item.color || "#0d8f83",initials:item.name.slice(0,2),photoUrl:item.photoUrl ?? undefined}))); }, [staffQuery.data]);
  useEffect(() => { if (servicesQuery.data) setServices(servicesQuery.data.map(item => ({id:item.id,name:item.name,duration:item.durationMinutes,price:item.price,category:item.category}))); }, [servicesQuery.data]);
  const updateBooking = (patch:Partial<Booking>) => { if (!selected) return; if (!tenantId) { notify("لا توجد مساحة عمل نشطة؛ لم يتم حفظ التعديل"); return; } bookingUpdate.mutate({tenantId,bookingId:selected.id,status:patch.status,paid:patch.paid,note:patch.note,durationMinutes:patch.duration,staffId:patch.staff,startMinutes:patch.start,date:patch.date}); };
  const removeNav = (id:string) => { setNavItems(items => items.filter(item => item.id !== id)); notify("تم إخفاء القسم من القائمة"); };
  const resetNav = () => { setNavItems(navDefaults); notify("تمت استعادة جميع الأقسام"); };

  return <div className={`app-shell ${compact ? "compact" : ""}`} style={{"--brand":accent} as React.CSSProperties}>
    <aside className={`sidebar ${sidebarOpen ? "open" : ""}`}>
      <div className="brand-lockup"><div className="brand-mark"><Sparkles size={21}/></div><div><strong>Clientora</strong><span>{t("منصة إدارة الحجوزات")}</span></div></div>
      <div className="workspace-switcher" onClick={() => {if(!isStaffAccount) setModal("company")}}><div className="workspace-avatar">{(workspaceQuery.data?.name ?? "C").slice(0,1).toUpperCase()}</div><div><b>{workspaceQuery.data?.name ?? "مساحة العمل"}</b><small>{[workspaceQuery.data?.city,workspaceQuery.data?.countryCode].filter(Boolean).join(" · ") || t("بيانات الموقع غير متاحة")}</small></div><ChevronDown size={16}/></div>
      <div className="nav-title">{t("مساحة العمل")}</div>
      <nav>{(isStaffAccount ? navItems.filter(item=>item.id==="dashboard") : navItems).map(item => { const Icon = item.icon; return <button key={item.id} className={`nav-item ${active === item.id ? "active" : ""}`} onClick={() => {setActive(item.id);setSidebarOpen(false)}}><Icon size={19}/><span>{navTranslation[item.id]?.[language] ?? item.label}</span><span className="nav-actions"><Pencil size={12} onClick={e => {e.stopPropagation(); setModal("customize")}}/></span></button> })}</nav>
      <div className="sidebar-spacer" />
      {!isStaffAccount && <button className="nav-item" onClick={() => setModal("customize")}><Settings size={19}/><span>{t("تخصيص المنصة")}</span></button>}
      <div className="salon-card"><div className="salon-photo">✦</div><div><b>{workspaceQuery.data?.name ?? "مساحة العمل"}</b><small>{workspaceQuery.data?.status === "active" ? t("الحساب نشط") : workspaceQuery.data?.status === "trial" ? t("فترة تجريبية") : workspaceQuery.data?.status === "suspended" ? t("الحساب موقوف") : t("حالة الحساب غير متاحة")}</small></div></div>
      {!isStaffAccount && <button className="owner-card" onClick={() => setModal("company")}><div className="owner-avatar">C</div><div><b>{t("إدارة الحساب")}</b><small>{t("إعدادات مساحة العمل")}</small></div><MoreVertical size={16}/></button>}
    </aside>
    <main className="main-area">
      <header className="topbar"><div className="mobile-brand"><button className="icon-button" onClick={() => setSidebarOpen(value => !value)} title={t("فتح القائمة")}><Menu size={20}/></button><b>Clientora</b></div><div className="topbar-title"><span>{language === "ar" ? "مساحة الشركة" : language === "en" ? "Company workspace" : "Рабочее пространство"}</span><b>{workspaceQuery.data?.name ?? "Clientora"}</b></div><div className="topbar-actions"><div className="language-switch-inline">{(["ar","en","ru"] as Language[]).map(code=><button type="button" key={code} className={language===code?"active":""} onClick={()=>setLanguage(code)}>{code.toUpperCase()}</button>)}</div>{!isStaffAccount && <button className="icon-button" onClick={() => setNotificationsOpen(value => !value)} title={t("فتح الإشعارات")}><Bell size={19}/>{(notificationsQuery.data?.length ?? 0) > 0 && <em>{Math.min(99,notificationsQuery.data?.length ?? 0)}</em>}</button>}{!isStaffAccount && <div className="topbar-popover-wrap"><button className="owner-menu" onClick={() => setOwnerMenuOpen(value => !value)}>أح <ChevronDown size={15}/></button>{ownerMenuOpen && <div className="topbar-popover owner-popover"><b className="language-title">{t("لغة المنصة")}</b>{(["ar","en","ru"] as Language[]).map(code => <button key={code} className={language === code ? "chosen-language" : ""} onClick={() => {setLanguage(code);setOwnerMenuOpen(false)}}>{languageName[code]}</button>)}<b className="language-title">{t("البلد والعملة")}</b>{countryOptions.map(item=><button key={item.code} className={country===item.code?"chosen-language":""} onClick={()=>{setCountry(item.code);localStorage.setItem("clientora-country",item.code);if(tenantId) updateSettings.mutate({tenantId,countryCode:item.code,currency:item.currency});setOwnerMenuOpen(false)}}>{t(item.name)} · {item.currency}</button>)}<button onClick={() => {setModal("company");setOwnerMenuOpen(false)}}><Store size={15}/> {t("تبديل الشركة")}</button></div>}</div>} {!isStaffAccount && <button className="primary-button" onClick={() => setModal("new")}><Plus size={18}/> {t("حجز جديد")}</button>}<button className="icon-button" onClick={() => logoutMutation.mutate()} title={t("تسجيل الخروج")} disabled={logoutMutation.isPending}><LogOut size={18}/></button></div></header>
      <section className="content-area">
        <div className="page-head"><div><div className="eyebrow">{dayText} <span className="live-dot"/> {language === "en" ? "Today" : language === "ru" ? "Сегодня" : "اليوم"}</div><h1>{active === "schedule" ? t("الجدول والحجوزات") : navTranslation[active]?.[language] ?? t(navItems.find(n => n.id === active)?.label || "لوحة التحكم")}</h1><p>{language === "en" ? "Manage your team and daily bookings in one workspace." : language === "ru" ? "Управляйте командой и ежедневными бронированиями в одном месте." : "تابع فريقك وحجوزاتك اليومية من مساحة تشغيل واحدة."}</p></div></div>
        {active === "dashboard" ? (isStaffAccount ? <EmployeeOverview tenantId={tenantId ?? 0} timezone={workspaceQuery.data?.timezone ?? "Asia/Muscat"} /> : <DashboardOverview tenantId={tenantId} timezone={workspaceQuery.data?.timezone ?? "Asia/Muscat"} currency={countryOptions.find(item=>item.code===country)?.currency ?? "ر.ع"} workspaceName={workspaceQuery.data?.name ?? "Clientora"} />) : active === "schedule" ? <>
          <div className="toolbar"><div className="date-controls"><button className="icon-button" onClick={() => setDateOffset(v => v - 1)}><ChevronRight size={18}/></button><button className="date-button" onClick={() => setDateOffset(0)} title={t("العودة إلى اليوم")}><CalendarDays size={17}/>{dayText}</button><button className="icon-button" onClick={() => setDateOffset(v => v + 1)}><ChevronLeft size={18}/></button><button className="soft-button" onClick={() => setDateOffset(0)}>{t("اليوم")}</button></div><div className="toolbar-tools"><div className="search-box"><Search size={17}/><input placeholder={t("ابحث باسم العميل أو الهاتف أو الخدمة")} value={query} onChange={e => setQuery(e.target.value)}/></div><select className="filter-select" value={filter} onChange={e => setFilter(e.target.value as Status|"all")}><option value="all">{t("كل الحالات")}</option><option value="new">{t("جديد")}</option><option value="confirmed">{t("مؤكد")}</option><option value="arrived">{t("حضر")}</option><option value="completed">{t("مكتمل")}</option><option value="cancelled">{t("ملغي")}</option></select><div className="segmented"><button className={view === "day" ? "selected" : ""} onClick={() => setView("day")}>{t("يوم")}</button><button className={view === "week" ? "selected" : ""} onClick={() => setView("week")}>{t("أسبوع")}</button></div><a className="outline-button booking-link" href="/book/glow-beauty-salon">{t("رابط الحجز")}</a></div></div>
          {view === "week" ? <div className="week-overview">{Array.from({length:7},(_,index)=>{const date=new Date(selectedIsoDate+"T12:00:00Z");date.setUTCDate(date.getUTCDate()+index);const iso=date.toISOString().slice(0,10);const dayBookings=filtered.filter(item=>item.date===iso);return <section className="week-day-card" key={iso}><header><b>{date.toLocaleDateString(weekLocale,{weekday:"long",timeZone:"UTC"})}</b><span>{date.toLocaleDateString(weekLocale,{day:"numeric",month:"short",timeZone:"UTC"})}</span><small>{dayBookings.length} {language === "en" ? "bookings" : language === "ru" ? "записей" : "حجز"}</small></header><div className="week-day-bookings">{dayBookings.length ? dayBookings.map(item=><button key={item.id} className={`week-booking ${statusMeta[item.status].className} ${selectedId===item.id?"selected":""}`} onClick={()=>setSelectedId(item.id)}><b>{timeLabel(item.start)} · {item.client}</b><span>{item.service} — {staff.find(person=>person.id===item.staff)?.name ?? t("الموظف")}</span></button>):<p>{t("لا توجد حجوزات")}</p>}</div></section>})}</div> : <div className="schedule-layout"><div className="calendar-card"><div className="calendar-scroll"><div className="calendar-grid" style={{gridTemplateColumns:`66px repeat(${staff.length}, minmax(160px, 1fr))`}}><div className="corner-cell">{t("الوقت")}</div>{staff.map(s => <div className="staff-head" key={s.id}><div className="staff-avatar" style={{background:s.color}}>{s.initials}</div><div><b>{s.name}</b><small>{s.role}</small></div><button className="icon-button staff-menu" onClick={() => setEditEntity({kind:"staff",id:s.id})} title={`تعديل ${s.name}`}><MoreVertical size={15}/></button></div>)}<div className="time-axis">{Array.from({length:19},(_,i) => <div key={i} style={{height:44}}>{timeLabel(540 + i*30)}</div>)}</div>{staff.map(s => <div className="staff-column" key={s.id} onDoubleClick={() => setModal("new")} onDragOver={e => e.preventDefault()} onDrop={() => { if(dragging && tenantId) { bookingUpdate.mutate({tenantId,bookingId:dragging,staffId:s.id}); setDragging(null); } }}>{filtered.filter(b => b.staff === s.id).map(b => <BookingCard key={b.id} booking={b} selected={selectedId === b.id} onSelect={() => setSelectedId(b.id)} onDragStart={() => setDragging(b.id)} onResize={duration=>updateBooking({duration})} />)}</div>)}{showCurrentTimeLine && <div className="current-time-line" style={{top:72+((currentMinutes-540)/30)*44}}><span>{new Intl.DateTimeFormat(locale,{hour:"2-digit",minute:"2-digit",timeZone:businessTimeZone}).format(currentTime)}</span></div>}</div></div><div className="calendar-footer"><span><i className="legend-dot new"/> {t("جديد")}</span><span><i className="legend-dot confirmed"/> {t("مؤكد")}</span><span><i className="legend-dot arrived"/> {t("حضر")}</span><span><i className="legend-dot cancelled"/> {t("ملغي")}</span><span className="footer-hint"><GripVertical size={14}/> {t("اسحب البطاقة لتغيير الموظف · اسحب أسفل البطاقة لتغيير المدة")}</span></div></div><BookingPanel booking={selected} staff={staff} onUpdate={updateBooking} onClose={() => setSelectedId(0)} /></div>}
        </> : <ManagementView active={active} tenantId={tenantId} onNew={() => active === "services" ? setNewServiceOpen(true) : active === "staff" ? setEditEntity({kind:"staff",id:0}) : setModal("new")} staff={staff} services={services} bookings={bookings} onEditStaff={id => setEditEntity({kind:"staff",id})} onEditService={id => setEditEntity({kind:"service",id})} onManageHours={id => setScheduleStaffId(id)} onInvite={id=>{if(tenantId)createInviteMutation.mutate({tenantId,staffId:id});}} />}
      </section>
    </main>
    {modal === "new" && <NewBookingModal onClose={() => setModal(null)} initialDate={isoDate(displayDate)} tenantId={tenantId ?? 0} staff={staff} services={services} pending={createBookingMutation.isPending} onCreate={input => {if(!tenantId)return notify("لا توجد مساحة عمل نشطة");if(input.date!==isoDate(displayDate)){const base=Date.parse(isoDate(today)+"T00:00:00Z");const target=Date.parse(input.date+"T00:00:00Z");setDateOffset(Math.round((target-base)/86400000));}createBookingMutation.mutate({tenantId,...input});}}/>}
    {modal === "customize" && <CustomizeModal accent={accent} setAccent={setAccent} compact={compact} setCompact={setCompact} navItems={navItems} onRemove={removeNav} onRename={(id,label) => setNavItems(items => items.map(item => item.id === id ? {...item,label} : item))} onIconChange={(id,iconKey) => setNavItems(items => items.map(item => item.id === id ? {...item,iconKey,icon:iconLibrary.find(x => x.key === iconKey)?.icon ?? item.icon} : item))} onReset={resetNav} onClose={() => setModal(null)} />}
    {modal === "company" && <CompanyModal onClose={() => setModal(null)} onChoose={_name => {notify("تبديل الشركات غير متاح بعد؛ لا توجد آلية اختيار فرع متصلة بالحساب.");setModal(null)}}/>}
    {editEntity?.kind === "staff" && <EditEntityModal kind="staff" record={staff.find(item => item.id === editEntity.id)} onClose={() => setEditEntity(null)} onSave={value => {if(!tenantId)return notify("أنشئ مساحة شركة أولاً");if(editEntity.id===0)addStaffMutation.mutate({tenantId,name:value.name ?? "",role:value.role ?? ""});else updateStaffMutation.mutate({tenantId,staffId:editEntity.id,name:value.name,staffRole:value.role});}}/>}
    {scheduleStaffId !== null && tenantId && <StaffHoursModal tenantId={tenantId} staffId={scheduleStaffId} staffName={staff.find(item => item.id === scheduleStaffId)?.name ?? "الموظف"} onClose={() => setScheduleStaffId(null)} onSaved={() => {setScheduleStaffId(null);notify("تم حفظ جدول دوام الموظف");}} />}
    {editEntity?.kind === "service" && <EditEntityModal kind="service" record={services.find(item => item.id === editEntity.id)} onClose={() => setEditEntity(null)} onSave={value => {if(!tenantId)return notify("أنشئ مساحة شركة أولاً");updateServiceMutation.mutate({tenantId,serviceId:editEntity.id,name:value.name,category:value.category,durationMinutes:value.duration,price:value.price});}}/>}
    {newServiceOpen && <EditEntityModal kind="service" onClose={() => setNewServiceOpen(false)} onSave={value => {if(!tenantId)return notify("أنشئ مساحة شركة أولاً");createServiceMutation.mutate({tenantId,name:value.name ?? "",category:value.category ?? "عام",durationMinutes:value.duration ?? 60,price:value.price ?? 0});}}/>}
    {toast && <div className="toast"><Check size={17}/>{toast}</div>}
  </div>;
}

function EmployeeOverview({tenantId,timezone}:{tenantId:number;timezone:string}) {
  const {language,t} = useLanguage();
  const locale = language === "en" ? "en-GB" : language === "ru" ? "ru-RU" : "ar";
  const today = isoDate(new Date(),timezone);
  const end = (()=>{const d=new Date(today+"T12:00:00Z");d.setUTCDate(d.getUTCDate()+6);return d.toISOString().slice(0,10);})();
  const query = trpc.workspace.employeeBookings.useQuery({tenantId,date:today,endDate:end},{enabled:tenantId>0,refetchInterval:60000});
  const rows = query.data ?? [];
  const todayRows = rows.filter(row=>row.date===today);
  const upcoming = todayRows.filter(row=>row.startMinutes>=(()=>{const p=new Intl.DateTimeFormat("en-GB",{timeZone:timezone,hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).format(new Date()).split(":").map(Number);return p[0]*60+p[1];})() && row.status!=="cancelled").sort((a,b)=>a.startMinutes-b.startMinutes);
  const statusLabel:Record<string,string>={new:t("جديد"),confirmed:t("مؤكد"),arrived:t("حضر"),completed:t("مكتمل"),cancelled:t("ملغي"),no_show:t("لم يحضر")};
  return <div className="employee-overview">
    <div className="employee-welcome"><span className="employee-eyebrow"><span className="dashboard-live-dot"/> {t("مساحة الموظف")}</span><h1>{t("أهلاً بك في يوم عملك 👋")}</h1><p>{t("تابع مواعيدك وخدماتك القادمة بسهولة.")}</p></div>
    {query.isLoading?<div className="dashboard-loading">{t("جارٍ تحميل مواعيدك...")}</div>:query.isError?<div className="dashboard-empty">{t("تعذر تحميل المواعيد. تأكد أن حسابك مرتبط بملف الموظف لدى الشركة.")}</div>:<>
      <div className="employee-kpis"><article><CalendarDays/><span>{t("حجوزات اليوم")}</span><strong>{todayRows.length}</strong></article><article><Clock3/><span>{t("المواعيد القادمة")}</span><strong>{upcoming.length}</strong></article><article><Check/><span>{t("مكتمل اليوم")}</span><strong>{todayRows.filter(row=>row.status==="completed").length}</strong></article></div>
      <section className="dashboard-panel employee-appointments"><div className="dashboard-panel-heading"><div><h2>{t("مواعيدي اليوم")}</h2><p>{t("بيانات الحجوزات المخصصة لك فقط")}</p></div><span className="upcoming-count">{todayRows.length}</span></div>
      {todayRows.length===0?<div className="dashboard-chart-empty">{t("لا توجد حجوزات مسجلة لك اليوم.")}</div>:<div className="upcoming-list">{todayRows.sort((a,b)=>a.startMinutes-b.startMinutes).map(row=><div className="upcoming-row" key={row.id}><div className="upcoming-avatar">{row.clientName.slice(0,1)||"؟"}</div><div className="upcoming-client"><strong>{row.clientName}</strong><span>{row.serviceName}</span></div><div className="upcoming-time"><Clock3 size={14}/>{timeLabel(row.startMinutes)}</div><span className={`upcoming-status status-${row.status}`}>{statusLabel[row.status]??row.status}</span></div>)}</div>}
      </section>
      <section className="dashboard-panel employee-week"><div className="dashboard-panel-heading"><div><h2>{t("نظرة الأسبوع")}</h2><p>{t("مواعيدك خلال الأيام السبعة القادمة")}</p></div></div><div className="employee-week-grid">{Array.from({length:7},(_,i)=>{const date=new Date(today+"T12:00:00Z");date.setUTCDate(date.getUTCDate()+i);const iso=date.toISOString().slice(0,10);const count=rows.filter(row=>row.date===iso&&row.status!=="cancelled").length;return <div key={iso}><small>{date.toLocaleDateString(locale,{weekday:"short",timeZone:"UTC"})}</small><b>{date.toLocaleDateString(locale,{day:"numeric",month:"short",timeZone:"UTC"})}</b><strong>{count}</strong><span>{t("حجز")}</span></div>})}</div></section>
    </>}
  </div>;
}

function BookingCard({booking,onSelect,selected,onDragStart,onResize}:{booking:Booking;onSelect:()=>void;selected:boolean;onDragStart:()=>void;onResize:(duration:number)=>void}) { const meta=statusMeta[booking.status]; const [resizing,setResizing]=useState(false); const startY=useRef(0); const startDuration=useRef(booking.duration); const move=(e:MouseEvent)=>{if(!resizing)return; const delta=Math.round((e.clientY-startY.current)/44)*30; onResize(Math.max(15,Math.min(480,startDuration.current+delta)));}; const stop=()=>{setResizing(false);window.removeEventListener("mousemove",move);window.removeEventListener("mouseup",stop);}; const begin=(e:React.MouseEvent)=>{e.preventDefault();e.stopPropagation();startY.current=e.clientY;startDuration.current=booking.duration;setResizing(true);window.addEventListener("mousemove",move);window.addEventListener("mouseup",stop);}; return <button draggable={!resizing} className={`booking-card ${meta.className} ${selected ? "selected" : ""}`} style={{top:((booking.start-540)/30)*44+3,height:Math.max(58,(booking.duration/30)*44-7)}} onClick={onSelect} onDragStart={onDragStart}><span className="booking-status"><Check size={11}/></span><b>{booking.client}</b><span>{booking.service}</span><small>{timeLabel(booking.start)} – {timeLabel(booking.start+booking.duration)} · {booking.price} ر.ع</small><MoreVertical className="booking-more" size={14}/><span className="booking-resize-handle" onMouseDown={begin} title="اسحب لتغيير مدة الحجز"><GripHorizontal size={14}/></span></button>; }
function BookingPanel({booking,staff,onUpdate,onClose}:{booking:Booking|null;staff:Staff[];onUpdate:(p:Partial<Booking>)=>void;onClose:()=>void}) { if(!booking) return <aside className="details-panel empty-panel"><CalendarDays size={28}/><p>اختر حجزاً لعرض تفاصيله</p></aside>; const meta=statusMeta[booking.status]; return <aside className="details-panel"><div className="panel-head"><div><span className="eyebrow">تفاصيل الحجز</span><h2>{booking.client}</h2></div><button className="icon-button" onClick={onClose}><X size={18}/></button></div><div className="client-profile"><div className="client-avatar">{booking.client.slice(0,1)}</div><div><b>{booking.client}</b><small>{booking.phone}</small></div><span className={`status-pill ${meta.className}`}>{meta.label}</span></div><div className="detail-section"><div className="section-label"><WalletCards size={16}/> الخدمة</div><div className="service-line"><div><b>{booking.service}</b><small>{booking.duration} دقيقة</small></div><strong>{booking.price} ر.ع</strong></div><div className="total-line"><span>الإجمالي</span><b>{booking.price} ر.ع</b></div></div><div className="edit-booking-fields"><label>الموظف<select value={booking.staff} onChange={e => onUpdate({staff:+e.target.value})}>{staff.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>وقت البداية<input type="time" value={`${String(Math.floor(booking.start/60)).padStart(2,"0")}:${String(booking.start%60).padStart(2,"0")}`} onChange={e => {const [h,m]=e.target.value.split(":").map(Number);onUpdate({start:h*60+m})}}/></label></div><div className="detail-list"><div><CalendarDays size={17}/><span><small>التاريخ والوقت</small><b>{timeLabel(booking.start)} – {timeLabel(booking.start+booking.duration)}</b></span></div><div><UserRound size={17}/><span><small>الموظف</small><b>{staff.find(s => s.id === booking.staff)?.name}</b></span></div><div><CircleDollarSign size={17}/><span><small>حالة الدفع</small><b className={booking.paid ? "paid" : "unpaid"}>{booking.paid ? "مدفوع" : "غير مدفوع"} · {booking.price} ر.ع</b></span></div></div><label className="field-label">ملاحظات</label><textarea defaultValue={booking.note} onBlur={e => onUpdate({note:e.target.value})} placeholder="أضف ملاحظة للحجز..."/><div className="panel-actions"><button className="primary-button full" onClick={() => onUpdate({status:"arrived"})} disabled={booking.status === "cancelled"}><Check size={18}/> تسجيل الوصول</button><button className="soft-button full" onClick={() => onUpdate({status:"completed"})} disabled={booking.status === "cancelled"}><Check size={18}/> إنهاء الخدمة وتفعيل التقييم</button><button className="outline-button full" onClick={() => onUpdate({paid:true})} disabled={booking.paid || booking.status === "cancelled"}><WalletCards size={17}/> {booking.paid ? "تم الدفع" : "تسجيل الدفع"}</button><button className="danger-button full" onClick={() => {if(booking.paid){window.alert("لا يمكن إلغاء حجز مدفوع قبل معالجة الاسترجاع المالي");return;}if(window.confirm(`هل تريد إلغاء حجز ${booking.client}؟`)) onUpdate({status:"cancelled"});}} disabled={booking.status === "cancelled"}><Trash2 size={17}/> {booking.status === "cancelled" ? "الحجز ملغي" : "إلغاء الحجز"}</button></div><button className="edit-booking" onClick={() => onUpdate({status: booking.status === "confirmed" ? "new" : "confirmed"})} disabled={booking.status === "cancelled"}><Pencil size={15}/> تعديل حالة الحجز</button></aside>; }
function NewBookingModal({onClose,onCreate,staff,services,initialDate,tenantId,pending}:{onClose:()=>void;onCreate:(input:{clientName:string;phone:string;serviceId:number;staffId:number;date:string;startMinutes:number;note?:string;paid:boolean})=>void;staff:Staff[];services:Service[];initialDate:string;tenantId:number;pending:boolean}) {
  const [client,setClient]=useState("");
  const [phone,setPhone]=useState("");
  const [serviceId,setServiceId]=useState(services[0]?.id ?? 0);
  const [staffId,setStaffId]=useState(staff[0]?.id ?? 0);
  const [date,setDate]=useState(initialDate);
  const [time,setTime]=useState(600);
  const [paid,setPaid]=useState(false);
  const [note,setNote]=useState("");
  const smartSchedule = trpc.workspace.smartSchedule.useQuery({tenantId,serviceId,date},{enabled:tenantId>0&&serviceId>0&&/^\d{4}-\d{2}-\d{2}$/.test(date)});
  const service=services.find(item=>item.id===serviceId);
  const suggestions=smartSchedule.data ?? [];
  return <Modal title="إنشاء حجز جديد" subtitle="اختر الخدمة والتاريخ لعرض الأوقات والموظفين المتاحين" onClose={onClose}><div className="modal-form">
    <label>اسم العميل<input autoFocus value={client} onChange={e=>setClient(e.target.value)} placeholder="اسم العميل"/></label>
    <label>رقم الهاتف<input dir="ltr" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+968 ..."/></label>
    <div className="form-row">
      <label>الخدمة<select value={serviceId} onChange={e=>setServiceId(Number(e.target.value))}>{services.map(item=><option key={item.id} value={item.id}>{item.name} · {item.duration} دقيقة · {item.price}</option>)}</select></label>
      <label>التاريخ<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label>
    </div>
    <div className="form-row">
      <label>الموظف<select value={staffId} onChange={e=>setStaffId(Number(e.target.value))}>{staff.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label>الوقت<select value={time} onChange={e=>setTime(Number(e.target.value))}>{Array.from({length:48},(_,i)=>i*30).filter(value=>value+ (service?.duration ?? 60)<=1440).map(value=><option key={value} value={value}>{timeLabel(value)}</option>)}</select></label>
    </div>
    <div className="detail-section">
      <div className="section-label"><Sparkles size={16}/> اقتراحات Clientora الذكية</div>
      {smartSchedule.isLoading ? <small>جارٍ البحث عن الأوقات المناسبة...</small> : smartSchedule.isError ? <small>تعذر تحميل الاقتراحات. يمكنك اختيار موظف ووقت يدويًا، وسيتم التحقق عند الحفظ.</small> : suggestions.length===0 ? <small>لا توجد أوقات متاحة حسب دوام الفريق وحجوزاته لهذا اليوم.</small> : <div className="suggestion-list">{suggestions.slice(0,5).map(item=><div className="service-line" key={item.staffId}><div><b>{item.staffName}</b><small>{item.workload} حجوزات غير ملغاة اليوم</small></div><div className="suggestion-times">{item.availableSlots.slice(0,4).map(slot=><button type="button" className={staffId===item.staffId&&time===slot?"primary-button":"soft-button"} key={slot} onClick={()=>{setStaffId(item.staffId);setTime(slot);}}>{timeLabel(slot)}</button>)}</div></div>)}</div>}
    </div>
    <label>حالة الدفع<select value={paid?"paid":"unpaid"} onChange={e=>setPaid(e.target.value==="paid")}><option value="unpaid">غير مدفوع</option><option value="paid">مدفوع</option></select></label>
    <label>ملاحظة<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="أي ملاحظات إضافية..."/></label>
    <div className="modal-actions"><button className="outline-button" onClick={onClose}>إلغاء</button><button className="primary-button" disabled={pending||!client.trim()||phone.trim().length<5||!serviceId||!staffId||!date} onClick={()=>onCreate({clientName:client.trim(),phone:phone.trim(),serviceId,staffId,date,startMinutes:time,note:note.trim()||undefined,paid})}>{pending?"جارٍ الحفظ...":<><Plus size={17}/> حفظ الحجز</>}</button></div>
  </div></Modal>;
}

function CustomizeModal({accent,setAccent,compact,setCompact,navItems,onRemove,onRename,onIconChange,onReset,onClose}:{accent:string;setAccent:(x:string)=>void;compact:boolean;setCompact:(x:boolean)=>void;navItems:NavItem[];onRemove:(x:string)=>void;onRename:(id:string,label:string)=>void;onIconChange:(id:string,iconKey:string)=>void;onReset:()=>void;onClose:()=>void}) { return <Modal title="تخصيص المنصة" subtitle="عدّل الألوان والأيقونات وأسماء الأقسام من هنا" onClose={onClose}><div className="customize-block"><div><b><Palette size={17}/> لون الهوية</b><small>غيّر اللون الرئيسي للأزرار والحالات</small></div><div className="color-options">{["#0d8f83","#4169c1","#9d4edd","#cf5b75","#c36b28"].map(c=><button key={c} style={{background:c}} className={accent===c?"chosen":""} onClick={()=>setAccent(c)}/>)}</div></div><div className="customize-block"><div><b><WandSparkles size={17}/> كثافة الجدول</b><small>عرض مضغوط للمواعيد الكثيفة</small></div><button className={`switch ${compact?"on":""}`} onClick={()=>setCompact(!compact)}><span/></button></div><div className="customize-list"><div className="list-head"><b>أقسام القائمة</b><button onClick={onReset}>استعادة</button></div>{navItems.map(item=><div className="custom-item" key={item.id}><GripVertical size={16}/><div className="custom-icon-picker">{iconLibrary.slice(0,4).map(option=>{const Icon=option.icon;return <button className={item.iconKey===option.key?"picked":""} key={option.key} onClick={()=>onIconChange(item.id,option.key)}><Icon size={14}/></button>})}</div><input value={item.label} onChange={e=>onRename(item.id,e.target.value)} aria-label={`اسم ${item.label}`}/><button onClick={()=>onRemove(item.id)}><X size={15}/></button></div>)}</div><button className="primary-button full" onClick={onClose}>حفظ التخصيص</button></Modal>; }
function CompanyModal({onClose,onChoose}:{onClose:()=>void;onChoose:(x:string)=>void}) {
  const [adding,setAdding]=useState(false); const [name,setName]=useState(""); const [slug,setSlug]=useState(""); const [city,setCity]=useState("");
  const tenants=trpc.platform.tenants.useQuery(); const create=trpc.workspace.createTenant.useMutation({onSuccess:tenant=>{tenants.refetch();onChoose(tenant.name)},onError:e=>window.alert(e.message)}); const setStatus=trpc.platform.setTenantStatus.useMutation({onSuccess:()=>tenants.refetch(),onError:e=>window.alert(e.message)});
  const submit=()=>{if(name.trim()&&slug.trim())create.mutate({name:name.trim(),slug:slug.trim().toLowerCase().replace(/\s+/g,"-"),city:city.trim()||undefined})};
  return <Modal title="شركاتك ومشاريعك" subtitle="أنت مالك المنصة وتتحكم في إضافة الصالونات وحالتها دون حذف بياناتها" onClose={onClose}>{!adding?<><div className="company-list">{(tenants.data??[]).map(tenant=><div className="company-item" key={tenant.id}><button className="company-choice" onClick={()=>onChoose(tenant.name)}><div className="company-logo">{tenant.name.slice(0,1)}</div><div><b>{tenant.name}</b><small>{tenant.city||"—"} · {tenant.status === "suspended" ? "موقوف" : tenant.status === "trial" ? "تجريبي" : "نشط"}</small></div></button><button className="company-status" onClick={()=>setStatus.mutate({tenantId:tenant.id,status:tenant.status === "suspended" ? "active" : "suspended"})}>{tenant.status === "suspended" ? "تفعيل" : "أرشفة"}</button></div>)}</div><button className="outline-button full" onClick={()=>setAdding(true)}>+ إضافة صالون / شركة جديدة</button></>:<div className="modal-form"><label>اسم الصالون أو الشركة<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="مثال: صالون روز"/></label><label>الرابط المختصر بالإنجليزية<input dir="ltr" value={slug} onChange={e=>setSlug(e.target.value)} placeholder="rose-salon"/></label><label>المدينة<input value={city} onChange={e=>setCity(e.target.value)} placeholder="مسقط، عُمان"/></label><p className="form-hint">سيتم إنشاء مساحة مستقلة منطقياً مع بقاءك مالكاً ومشرفاً عليها.</p><div className="modal-actions"><button className="outline-button" onClick={()=>setAdding(false)}>رجوع</button><button className="primary-button" onClick={submit} disabled={create.isPending}>{create.isPending?"جارٍ الإنشاء...":"إنشاء المشروع"}</button></div></div>}</Modal>;
}
function ManagementView({active,tenantId,onNew,staff,services,bookings,onEditStaff,onEditService,onManageHours,onInvite}:{active:string;tenantId?:number;onNew:()=>void;staff:Staff[];services:Service[];bookings:Booking[];onEditStaff:(id:number)=>void;onEditService:(id:number)=>void;onManageHours:(id:number)=>void;onInvite:(id:number)=>void}) {
  const {t} = useLanguage();
  const titles:Record<string,string>={dashboard:"نظرة عامة",clients:"العملاء",services:"الخدمات",staff:"الموظفون",finance:"المالية",reports:"التقارير"};
  const [selectedClientId,setSelectedClientId]=useState<number|null>(null);
  const [clientNoteDraft,setClientNoteDraft]=useState("");
  const clientsQuery=trpc.workspace.clients.useQuery({tenantId:tenantId??0},{enabled:Boolean(tenantId)&&active==="clients"});
  const profileQuery=trpc.workspace.clientProfile.useQuery({tenantId:tenantId??0,clientId:selectedClientId??0},{enabled:Boolean(tenantId)&&selectedClientId!==null});
  const addClientNote=trpc.workspace.addClientNote.useMutation({onSuccess:async()=>{setClientNoteDraft("");await profileQuery.refetch();}});
  const clients=clientsQuery.data??[];
  const saveClientNote=async()=>{if(!tenantId||selectedClientId===null||!clientNoteDraft.trim())return;await addClientNote.mutateAsync({tenantId,clientId:selectedClientId,note:clientNoteDraft.trim()});};
  return <div className="management-view"><div className="management-banner"><div><span className="eyebrow">{t("إدارة مركزية")}</span><h2>{t(titles[active] || "لوحة التحكم")}</h2><p>{active === "staff" ? t("عدّل اسم الموظف ودوره مباشرة من هنا.") : active === "services" ? t("عدّل اسم الخدمة والمدة والسعر والتصنيف.") : t("هذه الوحدة أصبحت قابلة للتشغيل من داخل المنصة.")}</p></div><button className="primary-button" onClick={onNew}><Plus size={17}/> {t("إضافة جديد")}</button></div>
    {active === "staff" && <div className="entity-table"><div className="table-head"><span>الموظف</span><span>{t("الدور والتخصص")}</span><span>{t("الحالة")}</span><span>{t("إجراء")}</span></div>{staff.map(item => <div className="entity-row" key={item.id}><div className="entity-main"><div className="staff-avatar" style={{background:item.color}}>{item.initials}</div><div><b>{item.name}</b><small>{t("متاح للحجوزات")}</small></div></div><span>{item.role}</span><span className="status-text"><i/> {t("نشط")}</span><div className="entity-actions"><button className="soft-button" onClick={() => onManageHours(item.id)}><Clock3 size={15}/> {t("ساعات العمل")}</button><button className="soft-button" onClick={() => onInvite(item.id)} title={`إنشاء دعوة لـ ${item.name}`}><UserRound size={15}/> {t("دعوة")}</button><button className="icon-button" onClick={() => onEditStaff(item.id)} title={`تعديل ${item.name}`}><Pencil size={16}/></button></div></div>)}</div>}
    {active === "services" && <div className="entity-table"><div className="table-head"><span>الخدمة</span><span>التصنيف</span><span>المدة</span><span>إجراء</span></div>{services.map(item => <div className="entity-row" key={item.id}><div className="entity-main"><div className="service-icon"><WalletCards size={17}/></div><div><b>{item.name}</b><small>{item.price} ر.ع</small></div></div><span>{item.category}</span><span>{item.duration} دقيقة</span><button className="icon-button" onClick={() => onEditService(item.id)} title={`تعديل ${item.name}`}><Pencil size={16}/></button></div>)}</div>}
    {active === "clients" && <div className="client-management">
      {clientsQuery.isLoading?<div className="report-empty">جارٍ تحميل العملاء...</div>:clients.length===0?<div className="report-empty">لا يوجد عملاء مسجلون في قاعدة بيانات هذه الشركة حتى الآن.</div>:<div className="entity-table"><div className="table-head"><span>العميل</span><span>الهاتف</span><span>الزيارات المسجلة</span><span>الملف</span></div>{clients.map(item=><div className="entity-row" key={item.id}><div className="entity-main"><div className="client-avatar">{item.name.slice(0,1)}</div><div><b>{item.name}</b><small>عميل مسجل</small></div></div><span dir="ltr">{item.phone||"—"}</span><span>{item.visits} زيارة</span><button className="icon-button" onClick={()=>setSelectedClientId(item.id)} title="فتح ملف العميل"><Pencil size={16}/></button></div>)}</div>}
      {selectedClientId!==null&&<Modal title="ملف العميل" subtitle="بيانات العميل وسجل الحجوزات والمدفوعات المسجلة" onClose={()=>setSelectedClientId(null)}>
        {profileQuery.isLoading?<p className="form-hint">جارٍ تحميل ملف العميل...</p>:profileQuery.data?<div className="modal-form">
          <div className="stats-row"><div className="stat-card"><small>الزيارات المكتملة</small><b>{profileQuery.data.visitCount}</b></div><div className="stat-card"><small>إجمالي المدفوع</small><b>{profileQuery.data.paidTotal} ر.ع</b></div><div className="stat-card"><small>إجمالي الحجوزات</small><b>{profileQuery.data.bookings.length}</b></div></div>
          <div className="client-profile-contact"><b>{profileQuery.data.client.name}</b><span dir="ltr">{profileQuery.data.client.phone||"لا يوجد رقم هاتف"}</span></div>
          <div className="report-section"><div className="section-heading"><b>ملاحظات دائمة عن العميل</b></div>
            <textarea className="form-input" rows={3} maxLength={2000} value={clientNoteDraft} onChange={event=>setClientNoteDraft(event.target.value)} placeholder="اكتب تفضيلات العميل أو معلومات مهمة للفريق..."/>
            <button className="primary-button" disabled={!clientNoteDraft.trim()||addClientNote.isPending} onClick={saveClientNote}>{addClientNote.isPending?"جارٍ الحفظ...":"حفظ الملاحظة"}</button>
            {profileQuery.data.notes.length?profileQuery.data.notes.map(note=><div className="expense-row" key={note.id}><div><small>{new Date(note.createdAt).toLocaleString("ar")}</small><b>{note.note}</b></div></div>):<div className="report-empty">لا توجد ملاحظات محفوظة لهذا العميل.</div>}
          </div>
          <div className="report-section"><div className="section-heading"><b>سجل الحجوزات</b></div>{profileQuery.data.bookings.length?profileQuery.data.bookings.map(item=><div className="expense-row" key={item.id}><div><b>{item.serviceName} · {item.staffName}</b><small>{item.date} · {timeLabel(item.startMinutes)} · {item.status}</small>{item.note&&<small>ملاحظة: {item.note}</small>}</div><strong>{item.totalPrice} ر.ع</strong><span className={item.paid?"paid":"status-text"}>{item.paid?"مدفوع":"غير مدفوع"}</span></div>):<div className="report-empty">لا توجد حجوزات لهذا العميل.</div>}</div>
        </div>:<p className="form-hint">تعذر تحميل ملف العميل.</p>}
      </Modal>}
    </div>}
    {active === "reports" && <ReportsPanel tenantId={tenantId}/>}
    {!["staff","services","clients","reports"].includes(active) && <><div className="stats-row"><div className="stat-card"><small>إجمالي العملاء</small><b>—</b><span>يتم حسابها من قاعدة البيانات</span></div><div className="stat-card"><small>حجوزات هذا الشهر</small><b>—</b><span>يتم حسابها من قاعدة البيانات</span></div><div className="stat-card"><small>نسبة الحضور</small><b>—</b><span>يتم حسابها من قاعدة البيانات</span></div></div><div className="empty-module"><Sparkles size={30}/><h3>واجهة {titles[active] || "الوحدة"}</h3><p>اختر الجدول أو التقارير لإدارة البيانات التشغيلية الفعلية.</p></div></>}
  </div>;
}


function StaffHoursModal({tenantId,staffId,staffName,onClose,onSaved}:{tenantId:number;staffId:number;staffName:string;onClose:()=>void;onSaved:()=>void}) {
  const weekdays=["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
  const defaults=()=>Object.fromEntries(weekdays.map((_,weekday)=>[weekday,{active:weekday!==5,openMinutes:600,closeMinutes:1320}])) as Record<number,{active:boolean;openMinutes:number;closeMinutes:number}>;
  const [schedule,setSchedule]=useState(defaults);
  const hoursQuery=trpc.workspace.staffHours.useQuery({tenantId,staffId});
  const save=trpc.workspace.saveStaffHours.useMutation();
  const timeOffQuery=trpc.workspace.staffTimeOff.useQuery({tenantId,staffId});
  const addTimeOff=trpc.workspace.addStaffTimeOff.useMutation({onSuccess:()=>timeOffQuery.refetch()});
  const deleteTimeOff=trpc.workspace.deleteStaffTimeOff.useMutation({onSuccess:()=>timeOffQuery.refetch()});
  const [offDate,setOffDate]=useState("");
  const [offReason,setOffReason]=useState("");
  useEffect(()=>{if(hoursQuery.data){const next=defaults();for(const item of hoursQuery.data)next[item.weekday]={active:item.active===1,openMinutes:item.openMinutes,closeMinutes:item.closeMinutes};setSchedule(next);}},[hoursQuery.data]);
  const update=(weekday:number,patch:Partial<{active:boolean;openMinutes:number;closeMinutes:number}>)=>setSchedule(current=>({...current,[weekday]:{...current[weekday],...patch}}));
  const toTime=(minutes:number)=>`${pad(Math.floor(minutes/60))}:${pad(minutes%60)}`;
  const fromTime=(value:string)=>{const [hour,minute]=value.split(":").map(Number);return hour*60+minute;};
  const submit=async()=>{try{await Promise.all(weekdays.map((_,weekday)=>save.mutateAsync({tenantId,staffId,weekday,...schedule[weekday]})));onSaved();}catch(error){window.alert(error instanceof Error?error.message:"تعذر حفظ ساعات العمل");}};
  return <Modal title={`ساعات عمل ${staffName}`} subtitle="حدد أيام العمل ووقت الفتح والإغلاق. ستُستخدم هذه الساعات في إظهار المواعيد المتاحة." onClose={onClose}>
    {hoursQuery.isLoading?<p className="form-hint">جارٍ تحميل جدول الدوام...</p>:<div className="modal-form">
      {weekdays.map((day,weekday)=><div className="staff-hours-row" key={day}>
        <label className="staff-hours-day"><input type="checkbox" checked={schedule[weekday].active} onChange={event=>update(weekday,{active:event.target.checked})}/><b>{day}</b></label>
        <label>من<input type="time" value={toTime(schedule[weekday].openMinutes)} disabled={!schedule[weekday].active} onChange={event=>update(weekday,{openMinutes:fromTime(event.target.value)})}/></label>
        <label>إلى<input type="time" value={toTime(schedule[weekday].closeMinutes)} disabled={!schedule[weekday].active} onChange={event=>update(weekday,{closeMinutes:fromTime(event.target.value)})}/></label>
      </div>)}
      <div className="staff-timeoff-block"><b>الإجازات والاستثناءات</b><div className="form-row"><label>تاريخ الإجازة<input type="date" value={offDate} onChange={event=>setOffDate(event.target.value)}/></label><label>السبب (اختياري)<input value={offReason} onChange={event=>setOffReason(event.target.value)} placeholder="إجازة شخصية"/></label></div><button className="soft-button" disabled={!offDate||addTimeOff.isPending} onClick={()=>addTimeOff.mutate({tenantId,staffId,date:offDate,reason:offReason||undefined},{onSuccess:()=>{setOffDate("");setOffReason("");}})}>إضافة يوم إجازة</button>{(timeOffQuery.data??[]).map(item=><div className="staff-timeoff-item" key={item.id}><span>{item.date} {item.reason?`· ${item.reason}`:""}</span><button className="icon-button" onClick={()=>deleteTimeOff.mutate({tenantId,staffId,timeOffId:item.id})} title="حذف الإجازة"><Trash2 size={15}/></button></div>)}</div>
      <div className="modal-actions"><button className="outline-button" onClick={onClose}>إلغاء</button><button className="primary-button" onClick={submit} disabled={save.isPending||hoursQuery.isLoading||weekdays.some((_,weekday)=>schedule[weekday].active&&schedule[weekday].closeMinutes<=schedule[weekday].openMinutes)}>{save.isPending?"جارٍ الحفظ...":"حفظ جدول الدوام"}</button></div>
    </div>}
  </Modal>;
}

function ReportsPanel({tenantId}:{tenantId?:number}) {
  const now=useMemo(()=>new Date(),[]); const fromDate=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}-01`; const toDate=isoDate(now);
  const [open,setOpen]=useState(false); const [category,setCategory]=useState("مشتريات"); const [description,setDescription]=useState(""); const [vendor,setVendor]=useState(""); const [amount,setAmount]=useState(""); const [paymentMethod,setPaymentMethod]=useState("نقدي");
  const reports=trpc.workspace.reports.useQuery({tenantId:tenantId??0,fromDate,toDate},{enabled:Boolean(tenantId)}); const expensesQuery=trpc.workspace.expenses.useQuery({tenantId:tenantId??0,fromDate,toDate},{enabled:Boolean(tenantId)});
  const add=trpc.workspace.addExpense.useMutation({onSuccess:()=>{expensesQuery.refetch();setOpen(false);setDescription("");setVendor("");setAmount("");},onError:e=>window.alert(e.message)});
  const totals=reports.data?.totals??{bookings:0,completed:0,cancelled:0,revenue:0,paidRevenue:0}; const expenseTotal=(expensesQuery.data??[]).reduce((sum,item)=>sum+item.amount,0); const insights=buildBusinessInsights({...totals,expenseTotal,employees:reports.data?.employees??[]});
  const weekdayNames=["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
  const demand=reports.data?.demand;
  const observedDays=(demand?.days??[]).filter(day=>day.bookings>0);
  const peakDay=[...observedDays].sort((a,b)=>b.bookings-a.bookings)[0];
  const peakHour=[...(demand?.hours??[])].sort((a,b)=>b.bookings-a.bookings)[0];
  const demandTotal=(demand?.sampleSize??0)+(demand?.cancelledBookings??0);
  const cancellationShare=demandTotal>0?Math.round((demand?.cancelledBookings??0)/demandTotal*100):0;
  const submit=()=>{if(tenantId&&description.trim()&&Number(amount)>0)add.mutate({tenantId,category,description:description.trim(),vendor:vendor.trim()||undefined,amount:Number(amount),date:toDate,paymentMethod});};
  return <div className="reports-panel"><div className="report-toolbar"><div><b>تقارير التشغيل</b><small>من بداية الشهر حتى {toDate}</small></div><button className="primary-button" onClick={()=>setOpen(true)}><Plus size={16}/> إضافة مصروف / مشتريات</button></div><div className="stats-row"><div className="stat-card"><small>إيراد الحجوزات</small><b>{totals.revenue} ر.ع</b><span>{totals.paidRevenue} ر.ع محصل فعلياً</span></div><div className="stat-card"><small>مصروفات ومشتريات</small><b>{expenseTotal} ر.ع</b><span>من السجل المالي الفعلي</span></div><div className="stat-card"><small>صافي التشغيل</small><b>{totals.revenue-expenseTotal} ر.ع</b><span>{totals.bookings} حجز · {totals.completed} حضر</span></div></div><section className="report-section business-intelligence"><div className="section-heading"><div><b><Sparkles size={17}/> ذكاء الأعمال — توصيات قابلة للتنفيذ</b><small>تحليل واضح مبني على حجوزات ومصروفات هذه الفترة، دون بيانات تجريبية</small></div><span className="insight-period">مؤشرات فعلية</span></div><div className="stats-row"><div className="stat-card"><small>مبالغ غير محصلة</small><b>{insights.unpaid.toLocaleString()}</b><span>فرق الإيراد المسجل عن المدفوع</span></div><div className="stat-card"><small>عدم الحضور</small><b>{Math.round(insights.noShowRate*100)}%</b><span>{insights.noShowCount} حالة</span></div><div className="stat-card"><small>صافي بعد المصروفات المسجلة</small><b>{insights.net.toLocaleString()}</b><span>ليس كشفاً محاسبياً نهائياً</span></div></div><div className="insight-list">{insights.recommendations.map((item,index)=><article className={`insight-card insight-${item.priority}`} key={item.title}><div className="insight-mark">{item.priority==="high"?"!":item.priority==="medium"?"↗":"✦"}</div><div><b>{item.title}</b><p>{item.detail}</p><small>الخطوة المقترحة: {item.action}</small></div></article>)}</div></section><section className="report-section demand-intelligence"><div className="section-heading"><div><b><Sparkles size={17}/> خريطة الطلب على الحجوزات</b><small>توزيع الحجوزات المسجلة حسب يوم الأسبوع وساعة البداية خلال الفترة المحددة</small></div><span className="insight-period">بيانات فعلية</span></div><div className="stats-row"><div className="stat-card"><small>أكثر الأيام حجزاً</small><b>{peakDay?weekdayNames[peakDay.weekday]:"—"}</b><span>{peakDay?peakDay.bookings+" حجز غير ملغى":"لا توجد بيانات كافية"}</span></div><div className="stat-card"><small>أكثر ساعات البداية نشاطاً</small><b>{peakHour?String(peakHour.hour).padStart(2,"0")+":00":"—"}</b><span>{peakHour?peakHour.bookings+" حجز غير ملغى":"لا توجد بيانات كافية"}</span></div><div className="stat-card"><small>نسبة الإلغاء</small><b>{cancellationShare}%</b><span>{demand?.cancelledBookings??0} حجز ملغى من إجمالي الحجوزات</span></div></div><div className="demand-day-list">{observedDays.length?[...observedDays].sort((a,b)=>a.weekday-b.weekday).map(day=><div className="demand-day-row" key={day.weekday}><span>{weekdayNames[day.weekday]}</span><div className="demand-day-track"><i style={{width:(peakDay?Math.round(day.bookings/peakDay.bookings*100):0)+"%"}}/></div><b>{day.bookings}</b></div>):<div className="report-empty">لا توجد حجوزات فعلية كافية لعرض توزيع الطلب في هذه الفترة.</div>}</div><p className="form-hint">هذه قراءة وصفية للحجوزات غير الملغاة وليست توقعاً للمستقبل. لا نعتبر الساعات التي لا تظهر هنا ساعات متاحة؛ يلزم ربطها بساعات عمل الفريق قبل اقتراح مواعيد هادئة.</p></section><div className="report-section"><div className="section-heading"><div><b>أداء كل موظف</b><small>الحجوزات والحضور والإيراد حسب الفترة</small></div></div><div className="entity-table report-table"><div className="table-head"><span>الموظف</span><span>الحجوزات</span><span>الحضور</span><span>الإيراد</span><span>المحصل</span></div>{reports.data?.employees.length?reports.data.employees.map(person=><div className="entity-row" key={person.id}><div className="entity-main"><div className="staff-avatar" style={{background:"#0d8f83"}}>{person.name.slice(0,2)}</div><div><b>{person.name}</b><small>{person.role}</small></div></div><span>{person.bookings}</span><span>{person.completed} · إلغاء {person.cancelled}</span><span>{person.revenue} ر.ع</span><span className="paid">{person.paidRevenue} ر.ع</span></div>):<div className="report-empty">لا توجد حجوزات فعلية لهذه الفترة.</div>}</div></div><div className="report-section"><div className="section-heading"><div><b>المصروفات والمشتريات</b><small>سجل مالي دائم مرتبط بالشركة</small></div></div><div className="expense-list">{expensesQuery.data?.length?expensesQuery.data.map(item=><div className="expense-row" key={item.id}><div><b>{item.description}</b><small>{item.category}{item.vendor?` · ${item.vendor}`:""} · {item.paymentMethod}</small></div><strong>{item.amount} ر.ع</strong><time>{item.date}</time></div>):<div className="report-empty">لم تتم إضافة مصروفات بعد.</div>}</div></div>{open&&<Modal title="إضافة مصروف أو مشتريات" subtitle="سيُحفظ السجل في قاعدة بيانات الشركة ويظهر في صافي التشغيل" onClose={()=>setOpen(false)}><div className="modal-form"><label>التصنيف<select value={category} onChange={e=>setCategory(e.target.value)}><option>مشتريات</option><option>رواتب</option><option>إيجار</option><option>كهرباء وماء</option><option>تسويق</option><option>أخرى</option></select></label><label>وصف المصروف<input autoFocus value={description} onChange={e=>setDescription(e.target.value)} placeholder="مثال: شراء منتجات شعر"/></label><label>المورد<input value={vendor} onChange={e=>setVendor(e.target.value)} placeholder="اسم المورد (اختياري)"/></label><div className="form-row"><label>المبلغ<input type="number" min="1" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0"/></label><label>طريقة الدفع<select value={paymentMethod} onChange={e=>setPaymentMethod(e.target.value)}><option>نقدي</option><option>بطاقة</option><option>تحويل</option></select></label></div><div className="modal-actions"><button className="outline-button" onClick={()=>setOpen(false)}>إلغاء</button><button className="primary-button" onClick={submit} disabled={add.isPending||!description.trim()||Number(amount)<=0}>{add.isPending?"جارٍ الحفظ...":"حفظ المصروف"}</button></div></div></Modal>}</div>;
}

function EditEntityModal({kind,record,onClose,onSave}:{kind:"staff"|"service";record?:Staff|Service;onClose:()=>void;onSave:(value:Partial<Staff & Service>)=>void}) {
  const staffRecord = kind === "staff" ? record as Staff : undefined;
  const serviceRecord = kind === "service" ? record as Service : undefined;
  const [name,setName] = useState(record?.name ?? ""); const [role,setRole] = useState(staffRecord?.role ?? ""); const [category,setCategory] = useState(serviceRecord?.category ?? ""); const [duration,setDuration] = useState(serviceRecord?.duration ?? 60); const [price,setPrice] = useState(serviceRecord?.price ?? 60);
  return <Modal title={kind === "staff" ? (record ? "تعديل بيانات الموظف" : "إضافة موظف جديد") : record ? "تعديل تفاصيل الخدمة" : "إضافة خدمة جديدة"} subtitle="أي تعديل تحفظه يظهر فوراً في الجدول وقائمة الحجز الأونلاين" onClose={onClose}><div className="modal-form"><label>اسم الخدمة أو الموظف<input autoFocus value={name} onChange={e => setName(e.target.value)} /></label>{kind === "staff" ? <label>الدور أو نوع التخصص<input value={role} onChange={e => setRole(e.target.value)} placeholder="مثال: أخصائية شعر" /></label> : <><div className="form-row"><label>تصنيف المنيو<input value={category} onChange={e => setCategory(e.target.value)} placeholder="مثال: المساج" /></label><label>المدة بالدقائق<input type="number" value={duration} onChange={e => setDuration(+e.target.value)} /></label></div><label>السعر<input type="number" value={price} onChange={e => setPrice(+e.target.value)} /></label></>}<div className="modal-actions"><button className="outline-button" onClick={onClose}>إلغاء</button><button className="primary-button" onClick={() => onSave(kind === "staff" ? {name,role} : {name,category,duration,price})} disabled={!name.trim() || (kind === "staff" && !role.trim())}><Check size={17}/> حفظ</button></div></div></Modal>;
}
function Modal({title,subtitle,children,onClose}:{title:string;subtitle?:string;children:React.ReactNode;onClose:()=>void}) { return <div className="modal-backdrop" onMouseDown={e=>e.currentTarget===e.target&&onClose()}><div className="modal-card"><div className="modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose}><X size={18}/></button></div>{children}</div></div>; }
